#!/usr/bin/env node
/**
 * Writes the CRM console's copy of the Lead Quality Score rules from the
 * server's `leadQuality.rules.ts`.
 *
 * Why a generated file rather than an import: the server is the authority (it
 * validates every save and scores every lead) and imports no `@duncit/*`
 * package by design (rule 40), while the settings form needs the same rules in
 * the browser to total, validate and preview as the admin types. Two
 * hand-written copies would drift — a form could accept a configuration the
 * server refuses — and trip the duplication gate. Same arrangement as
 * `generate-growth-formula.mjs`.
 *
 * Run `node scripts/generate-lead-quality-rules.mjs` after editing the rules;
 * `--check` fails instead of writing, which is what CI runs so a stale copy
 * cannot ship.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(ROOT, "server/src/modules/crm/leadQuality/leadQuality.rules.ts");
const OUT = join(ROOT, "portals/crm/src/lib/generated/lead-quality-rules.ts");
const NAME = "generate-lead-quality-rules";
const check = process.argv.includes("--check");

const source = readFileSync(SOURCE, "utf8").replaceAll("\r\n", "\n");
// The copy must stand alone in the browser bundle: one import would pull a
// server module into it.
if (/^\s*import\s/m.test(source)) {
  console.error(`${NAME}: ${SOURCE} has an import — the rules file must import nothing`);
  process.exit(1);
}
const headerEnd = source.indexOf("*/\n");
if (!source.startsWith("/**") || headerEnd === -1) {
  console.error(`${NAME}: ${SOURCE} no longer opens with a doc comment — update this script`);
  process.exit(1);
}
const body = source.slice(headerEnd + 3).replace(/^\n+/, "");

const file = `/**
 * GENERATED by \`node scripts/generate-lead-quality-rules.mjs\` from
 * \`server/src/modules/crm/leadQuality/leadQuality.rules.ts\`
 * — do not edit; change the server file and regenerate.
 *
 * The settings form validates and totals with this copy as the admin types;
 * the server validates with the original on every save. CI fails if the two differ.
 */

${body}`;

if (check) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8").replaceAll("\r\n", "\n");
  } catch {
    console.error(`${NAME}: ${OUT} is missing — run the script without --check`);
    process.exit(1);
  }
  if (current !== file) {
    console.error(
      `${NAME}: lead-quality-rules.ts is out of date with the server rules.\n` +
        "Run `node scripts/generate-lead-quality-rules.mjs` and commit the result.",
    );
    process.exit(1);
  }
  console.log(`${NAME}: lead-quality-rules.ts matches the server rules`);
} else {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, file, "utf8");
  console.log(`${NAME}: wrote ${OUT.slice(ROOT.length + 1)}`);
}
